INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9524, 'plPL', 'Uwięziona w cytadeli', 'Przymierze, tutaj?! Słuchaj uważnie, $N.$B$BKargath pojmał kilku naszych żołnierzy. Jest wśród nich kapitan Alina, ważna oficer. Musisz spróbować ją uratować, zanim zostanie stracona.$B$BNie martw się o mnie, znajdę sposób, żeby się wydostać, jak tylko złapię oddech.', 'Uratuj kapitan Alinę w Cytadeli Piekielnego Ognia, zanim zostanie stracona.$B$BTo zadanie trzeba ukończyć na heroicznym poziomie trudności lochu.', '', 'Wróć do kapitan Aliny na Przylądku Gavina w Górach Alterak.', 'Kapitan Alina uratowana', '', '', '', 0),
(9525, 'plPL', 'Uwięziona w cytadeli', 'Miałam dziś szczęście i uciekłam z więzienia Kargatha, $N. Kilku więźniów ma zostać straconych, a wśród nich ważny oficer.$B$BŚmierć kapitana Kościołama byłaby potężnym ciosem dla naszych sił. Musisz zrobić wszystko, by go uratować. Ja jestem zbyt słaba, by iść dalej...', 'Uratuj kapitana Kościołama w Cytadeli Piekielnego Ognia, zanim zostanie stracony.$B$BTo zadanie trzeba ukończyć na heroicznym poziomie trudności lochu.', '', 'Wróć do kapitana Kościołama na Przylądku Gavina w Górach Alterak.', 'Kapitan Kościołam uratowany', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9524, 'plPL', 'Dziękuję ci, $N. Przyznaję, że nie spodziewałam się, że ktoś ruszy nam na ratunek.$B$BZbiorę pozostałych więźniów i zaprowadzę ich z powrotem do Warowni Honoru.', 0);
