INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(13721, 'plPL', 'Przymierze śmie zapuszczać się tak głęboko w moją twierdzę? Przyprowadzić więźniów z Warowni Honoru i wezwać kata! Zapłacą życiem za to wtargnięcie!', '', 0),
(13722, 'plPL', 'Fałszywa Horda Thralla śmie zapuszczać się tak głęboko w moją twierdzę? Przyprowadzić więźniów z Thrallmaru i wezwać kata! Zapłacą życiem za to wtargnięcie!', '', 0),
(13863, 'plPL', 'Obedrę twoje kości z mięsa!', 'Obedrę twoje kości z mięsa!', 0),
(14029, 'plPL', '%s ryczy!', '', 0),
(14043, 'plPL', 'Ja nie lubić tego tu...', '', 0),
(14044, 'plPL', 'Hej, ty zakuty łbie!', '', 0),
(14045, 'plPL', 'My zabić jego przyjaciel!', '', 0),
(14046, 'plPL', 'Miażdżyć!', '', 0),
(14047, 'plPL', 'Może pozwolisz, że to ja będę mówił?', '', 0),
(14048, 'plPL', 'Jak ty miły, ja pozwolić ci żyć.', '', 0),
(14130, 'plPL', 'Błagaj o swoje marne życie!', '', 0),
(14132, 'plPL', 'Uciekaj, tchórzu, uciekaj!', '', 0),
(14136, 'plPL', 'To boleć!', '', 0),
(14137, 'plPL', 'Aaa! Nie boleć więcej!', '', 0),
(14138, 'plPL', 'To nie dobre łaskotki!', '', 0),
(14139, 'plPL', 'Skóra płonąć!', '', 0),
(14140, 'plPL', 'To boleć!', '', 0),
(14141, 'plPL', 'Aaaach!', '', 0),
(14142, 'plPL', 'Nie straszyć więcej!', '', 0),
(14144, 'plPL', 'Dość!', '', 0),
(14148, 'plPL', 'Twój ból mnie bawi!', '', 0),
(14149, 'plPL', 'Ból!', '', 0),
(14150, 'plPL', 'Boli!', '', 0),
(14151, 'plPL', 'Graaaggh!!', '', 0),
(14152, 'plPL', 'Dość!!', '', 0),
(14309, 'plPL', 'Najeźdźcy przełamali obronę!', '', 0),
(14310, 'plPL', 'Łucznicy, w szereg! Na mój znak!', '', 0),
(14311, 'plPL', 'Gotowi!', '', 0),
(15569, 'plPL', 'Możecie wziąć tego, już go nie potrzebuję!', '', 0),
(15572, 'plPL', 'Chcecie go? Dobrze, bierzcie!', '', 0),
(15573, 'plPL', 'Nie traćcie czasu na tego, jest słaby!', '', 0),
(15575, 'plPL', 'Tak, bijcie go bez litości! Ma czaszkę grubą jak ogr!\n', '', 0),
(15579, 'plPL', 'Jeden nędznik mniej. No dalej, bierzcie następnego!', '', 0),
(15582, 'plPL', 'I tak zamierzałem go zabić!', '', 0),
(15584, 'plPL', 'Ach, co za marnotrawstwo... następny!', '', 0),
(15589, 'plPL', 'Dziękuję, że oszczędziliście mi kłopotu. Teraz moja kolej na zabawę!\n', '', 0),
(15594, 'plPL', 'Chcecie walczyć z nami wszystkimi naraz? To może być zabawne!\n', '', 0),
(15595, 'plPL', 'No dalej, pokażcie mi prawdziwą walkę!', '', 0),
(16862, 'plPL', 'Cóż... za szkoda.', '', 0),
(16863, 'plPL', 'Więcej zabawy miałem przy torturowaniu parobków!', '', 0),
(16864, 'plPL', 'Już się nudzę!', '', 0),
(16865, 'plPL', 'Przegraliście.', '', 0),
(16866, 'plPL', 'Och, po prostu giń!', '', 0),
(16895, 'plPL', 'My zabić kogoś innego!', '', 0),
(16896, 'plPL', 'Jeszcze nie skończyłem, idioto!', '', 0),
(16898, 'plPL', 'Ty zostać tu. Ja iść zabić kogoś innego!', '', 0),
(16899, 'plPL', 'To nie jest śmieszne!', '', 0),
(16900, 'plPL', 'Ha ha ha.', '', 0),
(16901, 'plPL', 'Co ty wyprawiasz?', '', 0),
(16902, 'plPL', 'Ja się znudzić.', '', 0),
(16903, 'plPL', 'Znudzić? Przecież prawie nie żył!', '', 0),
(16916, 'plPL', 'Nie, NIE pozwolimy ci żyć.', '', 0),
(16917, 'plPL', 'Hej!', '', 0),
(16918, 'plPL', 'Ja głodny.', '', 0),
(16919, 'plPL', 'Ty zawsze głodny. Dlatego my tacy grubi!', '', 0),
(16921, 'plPL', 'Jestem zmęczony. Ty zabij następnego!', '', 0),
(16922, 'plPL', 'Ten umierać łatwo!', '', 0),
(16923, 'plPL', 'Bo to ja odwalam całą ciężką robotę!', '', 0),
(16924, 'plPL', 'To wszystko... twoja wina!', '', 0),
(16925, 'plPL', 'Nie... znoszę... cię.', '', 0),
(17614, 'plPL', 'To nasza Horda jest PRAWDZIWA! Jedyna Horda!', '', 0),
(17616, 'plPL', 'Obedrę twoje kości z mięsa!', '', 0),
(17617, 'plPL', 'Nie bez powodu zwą mnie Brzytworękim. Zaraz się przekonacie.', '', 0),
(17619, 'plPL', 'Za prawdziwą Hordę!', '', 0),
(17620, 'plPL', 'Jestem JEDYNYM wodzem wojennym!', '', 0),
(17621, 'plPL', 'Prawdziwa Horda... zwycięży.', '', 0),
(17910, 'plPL', 'Celuj!', '', 0),
(18367, 'plPL', 'Tchórze! Nigdy nie zwabicie mnie w cień!', '', 0),
(38754, 'plPL', 'Ja głodny.', '', 0);
